INSERT INTO faq_articles (slug, locale, category, sort_order, question, answer_md, tags, status, published_at) VALUES
  ('apa-itu-jastipkita', 'id', 'GENERAL', 10, 'Apa itu JastipKita?', 'JastipKita mempertemukan **Penitip** yang ingin membeli barang dari luar negeri dengan **Traveler** yang sedang bepergian. Penitip membuat request, Traveler mengajukan penawaran, dan seluruh pembayaran berjalan melalui SafePay. Rincian harga (harga barang, fee traveler, estimasi bea masuk & pajak, biaya layanan) selalu ditampilkan sebelum membayar.', ARRAY['umum', 'cara kerja']::text[], 'PUBLISHED', now()),
  ('apa-itu-safepay', 'id', 'PAYMENT', 20, 'Apa itu SafePay dan kapan dana diteruskan ke Traveler?', 'SafePay adalah alur pembayaran JastipKita. Dana Penitip diterima melalui mitra payment gateway dan dicatat terpisah untuk setiap transaksi. Dana **tidak** diteruskan ke Traveler sebelum barang diterima dan dikonfirmasi Penitip, atau dikonfirmasi otomatis 48 jam setelah status *Terkirim* bila tidak ada dispute.', ARRAY['safepay', 'pembayaran', 'dana']::text[], 'PUBLISHED', now()),
  ('kapan-traveler-boleh-membeli', 'id', 'TRAVELER', 30, 'Kapan Traveler boleh membeli barang titipan?', 'Hanya setelah status transaksi **Pembelian Disetujui** (PURCHASE_APPROVED), yang mensyaratkan pembayaran Penitip sudah diamankan SafePay. Sebelum status itu aplikasi Traveler menampilkan banner merah **DO NOT PURCHASE**. Pembelian sebelum waktunya menjadi risiko Traveler sendiri.', ARRAY['traveler', 'pembelian', 'do not purchase']::text[], 'PUBLISHED', now()),
  ('estimasi-bea-masuk', 'id', 'CUSTOMS', 40, 'Bagaimana bea masuk dan pajak impor dihitung?', 'Bea masuk dan pajak impor pada rincian harga adalah **estimasi** berdasarkan aturan kepabeanan yang berlaku saat penawaran dibuat; versi aturan yang dipakai dicatat pada setiap penawaran harga. Jumlah final ditetapkan petugas Bea dan Cukai. Bila Traveler membayar bea masuk, bukti pembayaran resmi wajib diunggah. Selisih antara estimasi dan tagihan resmi diproses sesuai Syarat & Ketentuan.', ARRAY['bea cukai', 'pajak', 'estimasi']::text[], 'PUBLISHED', now()),
  ('harga-barang-berubah', 'id', 'BUYER', 50, 'Bagaimana jika harga barang di toko berbeda?', 'Jika harga aktual berbeda lebih dari toleransi (2% atau maksimal Rp50.000), Traveler mengirim konfirmasi harga beserta foto struk/label. Penitip punya waktu 15 menit untuk menyetujui, menolak, atau meminta klarifikasi. Menolak kenaikan harga tidak dianggap kesalahan Penitip: transaksi dibatalkan dan dana dikembalikan penuh, termasuk biaya pembayaran, tanpa penalti Trust Score. Jika tidak ada respons sampai batas waktu, konfirmasi dianggap ditolak.', ARRAY['harga', 'konfirmasi harga']::text[], 'PUBLISHED', now()),
  ('cara-membuka-dispute', 'id', 'DISPUTE', 60, 'Bagaimana cara membuka dispute?', 'Dispute dapat dibuka dari halaman transaksi paling lambat 72 jam setelah barang berstatus terkirim. Kedua pihak mengunggah bukti dalam 72 jam; tim JastipKita menargetkan keputusan dalam 120 jam setelah bukti lengkap. Keputusan dapat diajukan banding satu kali dalam 72 jam.', ARRAY['dispute', 'komplain', 'refund']::text[], 'PUBLISHED', now()),
  ('jastipkita-credit', 'id', 'REFERRAL', 70, 'Apa itu JastipKita Credit?', 'JastipKita Credit adalah saldo potongan yang didapat dari program referral atau promo. Credit berlaku 90 hari, hanya dapat dipakai sebagai potongan saat checkout, dan tidak dapat dicairkan menjadi uang.', ARRAY['credit', 'referral']::text[], 'PUBLISHED', now())
